function sieve(n, rounds) { let c = 0; for (let r = 0; r < rounds; r++) { const s = new Uint8Array(n); for (let i = 2; i * i < n; i++) if (!s[i]) for (let j = i * i; j < n; j += i) s[j] = 1; for (let i = 2; i < n; i++) if (!s[i]) c++ } return c }
